(async () => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const norm = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

  if (automaRefData('variables', 'rowError')) return automaNextBlock();
  sessionStorage.setItem('automaStep', '點擊場地卡片');
  const finish = (error) => {
    sessionStorage.removeItem('automaStep');
    if (error) automaSetVariable('rowError', error);
    automaNextBlock();
  };
  const fail = (message) => finish(message);

  const row = automaRefData('loopData', 'row.data') || {};
  const target = norm(row['場地名稱']);
  if (!target) return fail('CSV 這一列缺少「場地名稱」');

  const findCard = () =>
    [...document.querySelectorAll('div.card-body')].find((c) =>
      [...c.querySelectorAll('h5')].some((h) => norm(h.textContent) === target)
    );

  let card = null;
  for (let i = 0; i < 50 && !card; i++) {
    card = findCard();
    if (!card) await sleep(200);
  }
  const link = card && card.querySelector('a');
  if (!link) return fail(`場地列表找不到「${target}」`);

  link.click();
  finish();
})();

try {
  const csvText = automaRefData('variables', 'csvText');
  if (typeof csvText !== 'string' || !csvText.trim()) throw new Error('讀不到 CSV 檔內容');
  const text = csvText.replace(/^\uFEFF/, '');
  const names = ['場地名稱','信箱','租用日期','租用時段','人數','申請單位及負責人名稱','活動名稱','活動編號'];

  // CSV 解析（支援雙引號、欄位內逗號與換行）
  const rows = [];
  let row = [], cell = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"' && text[i + 1] === '"') { cell += '"'; i++; }
      else if (ch === '"') inQuotes = false;
      else cell += ch;
    } else if (ch === '"') inQuotes = true;
    else if (ch === ',') { row.push(cell); cell = ''; }
    else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some(v => v !== '')) rows.push(row);
      row = [];
    } else cell += ch;
  }
  if (cell !== '' || row.length) { row.push(cell); if (row.some(v => v !== '')) rows.push(row); }

  // 第一列是標題列，用來確認選對檔案且編碼正確
  const header = (rows.shift() || []).map((h) => h.trim());
  const missingHeader = ['場地名稱', '信箱'].filter((h) => !header.includes(h));
  if (missingHeader.length) {
    throw new Error(
      `標題列缺少「${missingHeader.join('」「')}」欄位。請確認選對檔案，` +
      '並用 Excel「另存新檔」選擇「CSV UTF-8（逗號分隔）」格式'
    );
  }

  const data = rows.map(r => {
    const o = {};
    names.forEach((n, i) => o[n] = (r[i] || '').trim());
    return o;
  });

  if (!data.length) throw new Error('CSV 沒有任何資料列（第一列是標題）');

  automaSetVariable('csvRows', data);
  automaSetVariable('rowResults', []);
  automaSetVariable('rowError', '');
  automaNextBlock();
} catch (error) {
  sessionStorage.setItem('automaFatalDetail', error.message);
  automaNextBlock({ $error: true, message: error.message });
}

(async () => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const norm = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

  if (automaRefData('variables', 'rowError')) return automaNextBlock();
  sessionStorage.setItem('automaStep', '點擊我要租借');
  const finish = (error) => {
    sessionStorage.removeItem('automaStep');
    if (error) automaSetVariable('rowError', error);
    automaNextBlock();
  };
  const fail = (message) => finish(message);

  const row = automaRefData('loopData', 'row.data') || {};
  const target = norm(row['場地名稱']);
  if (!target) return fail('CSV 這一列缺少「場地名稱」');

  // 「我要租借」會在點擊當下讀取場地資料，資料未載入完成就點會缺少 housingSiteId
  const loaded = () => {
    const page = document.querySelector('main.facility-detail');
    if (!page) return false;
    const names = [...page.querySelectorAll('h3')].map((h) => norm(h.textContent));
    return names.includes(target);
  };

  for (let i = 0; i < 75 && !loaded(); i++) await sleep(200);

  const btn = loaded() &&
    [...document.querySelectorAll('main.facility-detail button')]
      .find((b) => norm(b.textContent) === '我要租借');
  if (!btn) return fail(`場地「${target}」的詳細資料沒有載入完成`);

  btn.click();
  finish();
})();

(async () => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const norm = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

  if (automaRefData('variables', 'rowError')) return automaNextBlock();
  sessionStorage.setItem('automaStep', '同意租借規約');
  const finish = (error) => {
    sessionStorage.removeItem('automaStep');
    if (error) automaSetVariable('rowError', error);
    automaNextBlock();
  };
  const fail = (message) => finish(message);

  const findAgreeBtn = () =>
    [...document.querySelectorAll('button')].find((b) =>
      norm(b.textContent).includes('我已詳閱並同意遵守本規約')
    );

  const formOpened = () =>
    [...document.querySelectorAll('h5, .modal-title')].some((el) =>
      norm(el.textContent).includes('預約申請表單')
    );

  const waitFor = async (predicate, attempts, interval) => {
    for (let i = 0; i < attempts; i++) {
      if (predicate()) return true;
      await sleep(interval);
    }
    return predicate();
  };

  let btn = null;
  for (let i = 0; i < 30 && !btn; i++) {
    btn = findAgreeBtn();
    if (!btn) await sleep(200);
  }
  if (!btn) return fail('找不到「我已詳閱並同意遵守本規約」按鈕');

  btn.click();
  let opened = await waitFor(formOpened, 40, 200);
  if (!opened) {
    const again = findAgreeBtn();
    if (again) again.click();
    opened = await waitFor(formOpened, 40, 200);
  }
  if (!opened) return fail('同意規約後沒有出現「預約申請表單」');

  finish();
})();

(async () => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const norm = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

  if (automaRefData('variables', 'rowError')) return automaNextBlock();
  sessionStorage.setItem('automaStep', '填寫預約申請表單');
  const finish = (error) => {
    sessionStorage.removeItem('automaStep');
    if (error) automaSetVariable('rowError', error);
    automaNextBlock();
  };
  const fail = (message) => finish(message);

  const row = automaRefData('loopData', 'row.data') || {};

  const missing = ['信箱', '租用日期', '人數', '申請單位及負責人名稱', '活動名稱']
    .filter((column) => !norm(row[column]));
  if (missing.length) return fail(`CSV 這一列缺少：${missing.join('、')}`);

  const findForm = () =>
    [...document.querySelectorAll('.modal-content')].find((m) =>
      [...m.querySelectorAll('h5')].some((h) => norm(h.textContent) === '預約申請表單')
    );

  const waitFor = async (getter, timeout = 5000) => {
    const end = Date.now() + timeout;
    while (Date.now() < end) {
      const value = getter();
      if (value) return value;
      await sleep(100);
    }
    return getter();
  };

  const setValue = async (el, value) => {
    el.focus();
    el.value = value;
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    el.blur();
    await sleep(200);
  };

  const toHalfWidth = (s) =>
    norm(s).replace(/[\uFF10-\uFF19]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xFEE0));

  const toDate = (s) => {
    const v = toHalfWidth(s);
    const m = v.match(/^(\d{4})(\d{2})(\d{2})$/) || v.match(/^(\d{4})\D(\d{1,2})\D(\d{1,2})$/);
    return m ? `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}` : v;
  };

  const toNumber = (s) => (toHalfWidth(s).match(/\d+/) || [''])[0];

  const toPeriod = (s) =>
    norm(s).replace(/\s/g, '').split('-')
      .map((t) => t.replace(/^(\d):/, '0$1:'))
      .join('-');

  const form = await waitFor(findForm, 10000);
  if (!form) return fail('找不到「預約申請表單」視窗');

  const byPlaceholder = (text) => form.querySelector(`input[placeholder="${text}"]`);
  const selectWith = (optionText) =>
    [...form.querySelectorAll('select')].find((s) =>
      [...s.options].some((o) => norm(o.textContent) === optionText)
    );
  const radio = (name, label) =>
    [...form.querySelectorAll(`input[type="radio"][name="${name}"]`)].find((r) =>
      norm(r.closest('label')?.textContent) === label
    );

  const unit = selectWith('請選擇使用單位');
  const youth = unit && [...unit.options].find((o) => norm(o.textContent) === '青創');
  if (!youth) return fail('「使用單位」沒有「青創」選項');
  await setValue(unit, youth.value);

  const email = byPlaceholder('請輸入信箱');
  if (!email) return fail('找不到「信箱」欄位');
  await setValue(email, norm(row['信箱']));

  const date = form.querySelector('input[type="date"]');
  if (!date) return fail('找不到「租用日期」欄位');
  const dateValue = toDate(row['租用日期']);
  await setValue(date, dateValue);
  if (date.value !== dateValue) {
    return fail(`租用日期「${norm(row['租用日期'])}」無法轉成 年-月-日`);
  }
  if (date.min && dateValue < date.min || date.max && dateValue > date.max) {
    return fail(`租用日期 ${dateValue} 不在可預約範圍 ${date.min} ~ ${date.max}`);
  }

  const wantPeriod = toPeriod(row['租用時段']);
  if (wantPeriod) {
    const period = await waitFor(() => {
      const s = selectWith('請選擇租用時段');
      return s && !s.disabled && s.options.length > 1 ? s : null;
    });
    if (!period) return fail(`${dateValue} 沒有可選的租用時段`);
    const option = [...period.options].find((o) =>
      !o.disabled && (toPeriod(o.value) === wantPeriod || toPeriod(o.textContent) === wantPeriod)
    );
    if (!option) {
      const choices = [...period.options].filter((o) => !o.disabled).map((o) => norm(o.textContent));
      return fail(`租用時段「${norm(row['租用時段'])}」不在可選時段內：${choices.join('、')}`);
    }
    await setValue(period, option.value);
  }

  const people = byPlaceholder('請填寫人數');
  if (!people) return fail('找不到「人數」欄位');
  const peopleValue = toNumber(row['人數']);
  await setValue(people, peopleValue);
  if (!peopleValue || people.value !== peopleValue) {
    return fail(`人數「${norm(row['人數'])}」無法轉成數字`);
  }

  const fields = [
    ['請填寫申請單位及負責人名稱', '申請單位及負責人名稱'],
    ['請填寫活動名稱', '活動名稱'],
  ];
  for (const [placeholder, column] of fields) {
    const el = byPlaceholder(placeholder);
    if (!el) return fail(`找不到「${column}」欄位`);
    await setValue(el, norm(row[column]));
  }

  const serial = await waitFor(() => byPlaceholder('請輸入活動編號'), 1500);
  if (serial && norm(row['活動編號'])) await setValue(serial, norm(row['活動編號']));

  // 冷氣選項只有場地有冷氣設備時才會出現
  const airYes = radio('isAirConditioner', '是');
  if (airYes) {
    airYes.click();
    await sleep(200);
  }

  const charityYes = radio('isCharity', '是');
  if (!charityYes) return fail('找不到「是否為公益性質」的「是」選項');
  charityYes.click();

  const charityItem = await waitFor(() =>
    [...form.querySelectorAll('.dropdown-item')].find((d) => norm(d.textContent) === '配合機關主辦之活動')
  );
  if (!charityItem) return fail('找不到公益性質「配合機關主辦之活動」');
  charityItem.click();
  await sleep(300);

  finish();
})();

(async () => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const norm = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

  if (automaRefData('variables', 'rowError')) return automaNextBlock();
  sessionStorage.setItem('automaStep', '送出申請');
  const finish = (error) => {
    sessionStorage.removeItem('automaStep');
    if (error) automaSetVariable('rowError', error);
    automaNextBlock();
  };
  const fail = (message) => finish(message);

  const LIST_URL = "https://citizen-scsp.thurc.org.taipei/#!/community/ba323527-9e1d-42b5-a661-c60eb6d46f7e/public-facility";

  const findForm = () =>
    [...document.querySelectorAll('.modal-content')].find((m) =>
      [...m.querySelectorAll('h5')].some((h) => norm(h.textContent) === '預約申請表單')
    );

  const form = findForm();
  if (!form) return fail('找不到「預約申請表單」視窗');

  const submit = [...form.querySelectorAll('button')].find((b) => norm(b.textContent) === '送出申請');
  if (!submit) return fail('找不到「送出申請」按鈕');
  submit.click();

  // 成功後網站會先顯示「新增成功」，有費用時再出現繳費提醒，最後跳到空間租借紀錄頁
  const end = Date.now() + 25000;
  let succeeded = false;
  while (Date.now() < end) {
    await sleep(300);

    if (/\/public-facility\/reservation/.test(location.hash)) {
      succeeded = true;
      break;
    }

    const feeNotice = [...document.querySelectorAll('.modal-content')].find((m) =>
      norm(m.textContent).includes('請於申請核可後')
    );
    const ok = feeNotice && [...feeNotice.querySelectorAll('button')].find((b) => norm(b.textContent) === '確定');
    if (ok) {
      ok.click();
      continue;
    }

    const errorList = document.querySelector('.modal-content ol.fs-5');
    if (errorList) return fail(`送出失敗：${norm(errorList.textContent)}`);

    const current = findForm();
    if (current && Date.now() > end - 23000) {
      const invalid = [...current.querySelectorAll('.invalid-feedback, .fs-tiny-1.text-danger')]
        .map((el) => norm(el.textContent))
        .filter(Boolean);
      if (invalid.length) return fail(`表單驗證未通過：${[...new Set(invalid)].join('；')}`);
    }
  }

  if (!succeeded) return fail('送出後未確認成功，可能已送出，請到空間租借紀錄確認');

  location.hash = new URL(LIST_URL).hash;
  for (let i = 0; i < 50; i++) {
    if (document.querySelector('.card-body h5')) break;
    await sleep(200);
  }

  finish();
})();

(() => {

  const automaPanel = (() => {
    const ID = 'automa-run-log';
    const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
    const btnCss = 'border:1px solid #fff;background:transparent;color:#fff;border-radius:4px;padding:0 6px;cursor:pointer;font-size:12px';

    const copyText = async (text) => {
      try {
        await navigator.clipboard.writeText(text);
      } catch (e) {
        const ta = document.createElement('textarea');
        ta.value = text;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        ta.remove();
      }
    };

    const ensure = () => {
      let el = document.getElementById(ID);
      if (el) return el;
      el = document.createElement('div');
      el.id = ID;
      el.style.cssText = 'position:fixed;top:12px;right:12px;z-index:2147483647;width:400px;max-height:75vh;display:flex;flex-direction:column;background:#fff;color:#222;border:1px solid #888;border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.3);font:13px/1.5 sans-serif;text-align:left';
      el.innerHTML =
        '<div style="display:flex;align-items:center;gap:6px;padding:6px 10px;background:#2a5599;color:#fff;border-radius:8px 8px 0 0">' +
        '<b style="flex:1">社宅場地租借 執行紀錄</b>' +
        `<button type="button" data-act="toggle" style="${btnCss}">收合</button>` +
        `<button type="button" data-act="close" style="${btnCss}">關閉</button></div>` +
        '<div data-part="status" style="padding:6px 10px;border-bottom:1px solid #ddd;font-weight:bold"></div>' +
        '<div data-part="body" style="overflow:auto;padding:6px 10px"></div>';
      el.addEventListener('click', async (e) => {
        const act = e.target && e.target.dataset ? e.target.dataset.act : null;
        if (act === 'close') el.remove();
        if (act === 'toggle') {
          const body = el.querySelector('[data-part="body"]');
          const hidden = body.style.display === 'none';
          body.style.display = hidden ? '' : 'none';
          e.target.textContent = hidden ? '收合' : '展開';
        }
        if (act === 'copy') {
          await copyText(el.dataset.copy || '');
          e.target.textContent = '已複製';
        }
      });
      document.body.appendChild(el);
      return el;
    };

    const describe = (r) =>
      `第 ${r.no} 筆（CSV 第 ${r.csvLine} 列）${r.place || '(無場地名稱)'} ${r.date || ''} ${r.period || ''}`.trim();

    const failedText = (results) => {
      const failed = results.filter((r) => !r.ok);
      if (!failed.length) return '';
      const header = ['筆數', 'CSV列', '場地名稱', '租用日期', '租用時段', '活動名稱', '失敗原因'].join('\t');
      const lines = failed.map((r) =>
        [r.no, r.csvLine, r.place, r.date, r.period, r.activity, r.error].map((v) => String(v ?? '').replace(/\s+/g, ' ')).join('\t')
      );
      return [header, ...lines].join('\n');
    };

    const render = ({ status, color = '#222', results = [], extraHtml = '', copy = '' }) => {
      const el = ensure();
      const statusEl = el.querySelector('[data-part="status"]');
      statusEl.textContent = status;
      statusEl.style.color = color;
      const rows = results.map((r) =>
        `<div style="padding:3px 0;border-bottom:1px dashed #eee;color:${r.ok ? '#1a7f37' : '#c62828'}">` +
        `<b>${r.ok ? '成功' : '失敗'}</b> ${esc(describe(r))}` +
        (r.ok ? '' : `<div style="padding-left:12px">原因：${esc(r.error)}</div>`) +
        '</div>'
      ).join('');
      el.dataset.copy = copy;
      el.querySelector('[data-part="body"]').innerHTML =
        extraHtml + (rows || '<div style="color:#888">尚無完成的資料</div>') +
        (copy ? '<div style="padding-top:8px"><button type="button" data-act="copy" style="border:1px solid #2a5599;background:#2a5599;color:#fff;border-radius:4px;padding:2px 10px;cursor:pointer">複製失敗清單</button></div>' : '');
    };

    return { render, describe, failedText, esc };
  })();

  const row = automaRefData('loopData', 'row.data') || {};
  const index = Number(automaRefData('loopData', 'row.$index')) || 0;
  const total = (automaRefData('variables', 'csvRows') || []).length;
  const results = automaRefData('variables', 'rowResults') || [];

  sessionStorage.removeItem('automaStep');
  automaSetVariable('rowError', '');

  automaPanel.render({
    status: `執行中：第 ${index + 1} / ${total} 筆　${row['場地名稱'] || ''} ${row['租用日期'] || ''}`,
    color: '#2a5599',
    results,
  });

  automaNextBlock();
})();

